final class BCLIBCFFI_Atmosphere extends ffi.Struct {
  /// < Temperature at base altitude (°F)
  @ffi.Double()
  external double t0;

  /// < Base altitude (ft)
  @ffi.Double()
  external double a0;

  /// < Pressure at base altitude (hPa)
  @ffi.Double()
  external double p0;

  /// < Speed of sound (fps)
  @ffi.Double()
  external double mach;

  /// < Air density / standard density
  @ffi.Double()
  external double density_ratio;

  /// < Lowest allowed temperature (°C)
  @ffi.Double()
  external double cLowestTempC;

  static ffi.Pointer<BCLIBCFFI_Atmosphere> $allocate(
    ffi.Allocator $allocator, {
    required double t0,
    required double a0,
    required double p0,
    required double mach,
    required double density_ratio,
    required double cLowestTempC,
  }) => $allocator<BCLIBCFFI_Atmosphere>()
    ..ref.t0 = t0
    ..ref.a0 = a0
    ..ref.p0 = p0
    ..ref.mach = mach
    ..ref.density_ratio = density_ratio
    ..ref.cLowestTempC = cLowestTempC;
}

final class BCLIBCFFI_BaseTrajData extends ffi.Struct {
